+PackedVector2Array VisualShape2D::_get_shape_points() const {
+	// In range [-1,1].
+	PackedVector2Array points = PackedVector2Array();
+	switch (shape_type) {
+		case SHAPE_RECTANGLE: {
+			points = {
+				Vector2(-1, 1),
+				Vector2(-1, -1),
+				Vector2(1, -1),
+				Vector2(1, 1)
+			};
+		} break;
+		case SHAPE_CIRCLE: {
+			float angle = Math_TAU / resolution;
+			points.resize(resolution);
+			for (int i = 0; i < resolution; i++) {
+				points.write[i] = Vector2(Math::sin(i * angle), -Math::cos(i * angle));
+			}
+		} break;
+		case SHAPE_EQUILATERAL_TRIANGLE: {
+			points = {
+				Vector2(-1, 1),
+				Vector2(0, -1),
+				Vector2(1, 1)
+			};
+		} break;
+		case SHAPE_RIGHT_TRIANGLE: {
+			points = {
+				Vector2(-1, 1),
+				Vector2(-1, -1),
+				Vector2(1, 1)
+			};
+		} break;
+		case SHAPE_CAPSULE: {
+			// Also see CapsuleShape2D::_get_points().
+			int capsule_res = resolution;
+			// Must be even.
+			if (resolution % 2 == 1) {
+				capsule_res += 1;
+			}
+			points.resize(capsule_res + 2);
+			int first_half = capsule_res / 2;
+			real_t turn_step = Math_TAU / capsule_res;
+			real_t radius = MIN(size.x, size.y);
+			real_t height = MAX(size.x, size.y);
+			if (radius == height) {
