+			if (size.y >= size.x) {
+				capsule_offset = Vector2(0, 1.0 - radius / height);
+			} else {
+				capsule_offset = Vector2(1.0 - radius / height, 0);
+			}
+
+			int index = 0;
+			for (int i = 0; i < capsule_res; i++) {
